"use client";

import {
    X,
    Calendar,
    User,
    FileText,
    MapPin,
    CreditCard,
    ExternalLink,
    Clock,
    CheckCircle2,
    XCircle,
    Info,
    ShieldCheck,
    Truck,
    Smartphone,
    Mail,
    Globe,
    FileEdit
} from "lucide-react";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";
import { calculateCommission } from "@/lib/rulesEngine";
import { ReceiptText, ChevronDown, ChevronUp } from "lucide-react";

interface OrderDetailsModalProps {
    isOpen: boolean;
    onClose: () => void;
    order: any;
}

const STATUS_CONFIG: Record<string, { icon: any; label: string; className: string }> = {
    Pendente: {
        icon: Clock,
        label: "Aguardando Pagamento",
        className: "bg-amber-50 text-amber-700 ring-amber-600/20 dark:bg-amber-400/10 dark:text-amber-400 dark:ring-amber-400/20",
    },
    Rascunho: {
        icon: FileEdit,
        label: "Aguardando Finalização",
        className: "bg-slate-50 text-slate-600 ring-slate-600/20 dark:bg-slate-400/10 dark:text-slate-400 dark:ring-slate-400/20",
    },
    Pago: {
        icon: CheckCircle2,
        label: "Pago",
        className: "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-400/10 dark:text-emerald-400 dark:ring-emerald-400/20",
    },
    Emitido: {
        icon: CheckCircle2,
        label: "Emitido",
        className: "bg-blue-50 text-blue-700 ring-blue-600/20 dark:bg-blue-400/10 dark:text-blue-400 dark:ring-blue-400/20",
    },
    Aprovado: {
        icon: CheckCircle2,
        label: "Pronto p/ Emitir",
        className: "bg-cyan-50 text-cyan-700 ring-cyan-600/20 dark:bg-cyan-400/10 dark:text-cyan-400 dark:ring-cyan-400/20 animate-pulse",
    },
    Cancelado: {
        icon: XCircle,
        label: "Cancelado",
        className: "bg-rose-50 text-rose-700 ring-rose-600/20 dark:bg-rose-400/10 dark:text-rose-400 dark:ring-rose-400/20",
    },
};

export default function OrderDetailsModal({ isOpen, onClose, order }: OrderDetailsModalProps) {
    if (!isOpen || !order) return null;

    const statusCfg = STATUS_CONFIG[order.status] || STATUS_CONFIG["Pendente"];
    const StatusIcon = statusCfg.icon;
    const { currentUser } = useSimulation();
    const [showCalcMemory, setShowCalcMemory] = useState(false);

    // Stored memory has priority for historical accuracy. 
    // Fallback to recalculation only if legacy order.
    const steps = order.calculation_memory || (order.products ? calculateCommission(
        order.final_price,
        currentUser.level,
        order.category === "CNPJ",
        undefined,
        order.products.supplier_products ? {
            base_cost: order.products.supplier_products.base_cost,
            tax_fixed: order.products.supplier_products.supplier_tables?.tax_fixed || 0,
            tax_percent: order.products.supplier_products.supplier_tables?.tax_percent || 0
        } : undefined,
        {
            bronze: Number(order.products.commission_bronze) || 0,
            prata: Number(order.products.commission_prata) || 0,
            ouro: Number(order.products.commission_ouro) || 0
        }
    ).calculationSteps : null);

    const calcLabel = order.calculation_memory ? "Memória de Cálculo (Histórico)" : "Memória de Cálculo (Recalculado)";

    const formatCurrency = (value: number) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
    };

    const details = [
        { label: "Titular", value: order.holder_name || order.holder, icon: User },
        { label: "Documento", value: order.doc, icon: FileText },
        { label: "Produto", value: order.product, icon: ShieldCheck },
        { label: "Protocolo", value: order.protocol, icon: Info, mono: true },
    ];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-300" onClick={onClose} />

            <div className="relative w-full max-w-xl bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-hidden border border-slate-200 dark:border-slate-800 flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-300">

                {/* ── Header ── */}
                <div className="p-5 border-b border-slate-100 dark:border-slate-800 shrink-0">
                    <div className="flex items-center justify-between mb-1">
                        <span className={cn(
                            "inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wider",
                            statusCfg.className
                        )}>
                            <StatusIcon size={12} />
                            {statusCfg.label}
                        </span>
                        <button onClick={onClose} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-all">
                            <X size={18} className="text-slate-400" />
                        </button>
                    </div>
                    <h2 className="text-lg font-bold text-slate-900 dark:text-white tracking-tight">
                        {order.holder_name || order.holder}
                    </h2>
                    <div className="flex items-center gap-2 mt-1">
                        <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wider">
                            Protocolo: <span className="font-mono text-slate-500">{order.protocol}</span>
                        </span>
                        <span className="text-slate-200 dark:text-slate-800">•</span>
                        <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wider">
                            {order.date || format(new Date(order.created_at), "dd/MM/yyyy", { locale: ptBR })}
                        </span>
                    </div>
                </div>

                {/* ── Content ── */}
                <div className="overflow-y-auto p-5 space-y-6 custom-scrollbar">

                    {/* Basic Grid - Simplified */}
                    <div className="grid grid-cols-2 gap-y-4">
                        {details.map((item, idx) => (
                            <div key={idx} className="flex flex-col">
                                <span className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-0.5">{item.label}</span>
                                <span className={cn("text-xs font-semibold text-slate-700 dark:text-slate-200", item.mono && "font-mono")}>
                                    {item.value || "—"}
                                </span>
                            </div>
                        ))}
                    </div>

                    <div className="h-px bg-slate-100 dark:bg-slate-800" />

                    {/* Financial Section - Minimalist */}
                    <div>
                        <div className="flex justify-between items-end mb-4">
                            <div className="flex flex-col">
                                <span className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-1">Valor do Pedido</span>
                                <span className="text-2xl font-bold text-slate-900 dark:text-white leading-none">
                                    {formatCurrency(order.final_price || 0)}
                                </span>
                            </div>
                            <div className="flex flex-col items-end">
                                <span className="text-[9px] font-bold uppercase tracking-widest text-emerald-500 mb-1">Comissão</span>
                                <span className="text-xl font-bold text-emerald-600 dark:text-emerald-400 leading-none">
                                    {formatCurrency(order.seller_commission || 0)}
                                </span>
                            </div>
                        </div>

                        {/* Calculation Memory - Simplified */}
                        {steps && (
                            <div className="border border-slate-100 dark:border-slate-800 rounded-xl overflow-hidden">
                                <button
                                    type="button"
                                    onClick={() => setShowCalcMemory(!showCalcMemory)}
                                    className="w-full flex items-center justify-between px-3 py-2 bg-slate-50 dark:bg-slate-800/30 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                                >
                                    <div className="flex items-center gap-2">
                                        <ReceiptText size={12} className="text-slate-400" />
                                        <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{calcLabel}</p>
                                    </div>
                                    {showCalcMemory ? <ChevronUp size={14} className="text-slate-400" /> : <ChevronDown size={14} className="text-slate-400" />}
                                </button>

                                {showCalcMemory && (
                                    <div className="p-3 bg-white dark:bg-slate-900 space-y-2 border-t border-slate-100 dark:border-slate-800 animate-in fade-in duration-200">
                                        {steps.map((step: any, idx: number) => (
                                            <div key={idx} className="flex justify-between items-center text-[10px]">
                                                <span className="text-slate-400 font-medium">{step.label}</span>
                                                <span className={cn(
                                                    "font-semibold",
                                                    step.type === "positive" ? "text-emerald-500 font-bold" :
                                                        step.type === "negative" ? "text-rose-500" :
                                                            "text-slate-600 dark:text-slate-300"
                                                )}>
                                                    {step.value > 0 ? "+" : ""}{step.value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Integrated Data - Minimalist Dark Mode Support */}
                    {order.supplier_uuid && (
                        <div className="p-4 rounded-xl bg-slate-100/50 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-800 shadow-sm">
                            <div className="flex items-center gap-2 mb-3">
                                <Globe size={12} className="text-primary" />
                                <h3 className="text-[9px] font-bold uppercase tracking-widest text-slate-500">CERTIFICADORA</h3>
                            </div>

                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <div>
                                    <span className="text-[8px] font-bold uppercase text-slate-400 block mb-0.5">PEDIDO</span>
                                    <span className="text-xs font-mono font-bold text-slate-700 dark:text-slate-300">{order.supplier_order_id}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-[8px] font-bold uppercase text-slate-400 block mb-0.5">Status</span>
                                    <span className="text-xs font-bold text-primary">{order.supplier_status}</span>
                                </div>
                            </div>

                            <div className="flex gap-2">
                                {order.supplier_link_pagamento && (
                                    <button
                                        onClick={() => window.open(order.supplier_link_pagamento, '_blank')}
                                        className="flex-1 px-3 py-2 border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 rounded-lg text-[10px] font-bold uppercase transition-all hover:bg-slate-50 dark:hover:bg-slate-800 active:scale-95 shadow-sm"
                                    >
                                        Pagamento
                                    </button>
                                )}
                                {order.supplier_link_agendamento && (
                                    <button
                                        onClick={() => window.open(order.supplier_link_agendamento, '_blank')}
                                        className="flex-1 px-3 py-2 bg-primary text-white rounded-lg text-[10px] font-bold uppercase transition-all hover:opacity-90 active:scale-95 shadow-md shadow-primary/10"
                                    >
                                        Agendar
                                    </button>
                                )}
                            </div>
                        </div>
                    )}

                    {/* Address Detail - Simple Box */}
                    {order.address_details && (
                        <div>
                            <span className="text-[9px] font-bold uppercase tracking-widest text-slate-400 block mb-2">Endereço</span>
                            <div className="text-xs text-slate-600 dark:text-slate-300 space-y-0.5 pl-1 border-l-2 border-slate-100 dark:border-slate-800">
                                <p className="font-semibold text-slate-800 dark:text-slate-200">
                                    {order.address_details.street}, {order.address_details.number}
                                </p>
                                <p>{order.address_details.neighborhood}</p>
                                <p>{order.address_details.city} — {order.address_details.state} · {order.address_details.cep}</p>
                            </div>
                        </div>
                    )}
                </div>

                {/* ── Footer ── */}
                <div className="px-5 py-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">
                        Origem: {order.origin}
                    </span>
                    <button
                        onClick={onClose}
                        className="text-[10px] font-bold uppercase tracking-widest text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors"
                    >
                        Fechar
                    </button>
                </div>
            </div>
        </div>
    );
}
